    shNames: { standard: 'Official rule (active)', shadow_v3: 'v3 (active from 2026-10-01)', shadow_B: 'Shadow B: hard-data confirmation', shadow_C: 'Shadow C: new 12-month high → Offensive', spy: 'Buy & hold SPY' },
    shDefs: { shadow_B: 'v3, but only real-economy signals (unemployment, claims, industrial production) can keep it out of Offensive; leading indicators (yield curve, financial conditions, credit spreads) only warn', shadow_C: 'v3, but a new 12-month high in SPY turns Balanced into Offensive (except during a tightening shock)' },
    shNote: 'Backtests use the standard cash preset (0/40/80), net of costs, from 1993; live figures are computed daily from the record since 2026-09-25. The shadows’ backtest edge comes entirely after 2010 (mostly the 2023–24 inverted-curve false alarm), so only future live data can show whether they are really better.',
    tocCore: '📈 Record & paper portfolios',
