    coreLede: 'This is the site’s one core number: how much of the portfolio to hold in stocks under the current rule and your cash preset (the rest in short-term Treasuries). It updates once a day and is appended to <a href="data/history.csv">history.csv</a>, never edited afterwards — so the record from 2026-09-25 on is a genuine ex-ante record that can be checked over the years. The grey part is the same rule recomputed back to 1993, not signals actually issued at the time.',
    coreNow: (e, name, d) => `<div class="big">${e}</div><div>recommended equity share (${name}) · ${d}</div>`,
    coreLiveStat: (v, name, days) => `<div class="big">${v}</div><div>paper portfolio value (${name}, from $100,000) · ex-ante record ${days} trading days</div>`,
    coreBack: 'Recomputed (since 1993)', coreLive: 'Live record (since 2026-09-25)', coreStart: 'Live start',
