    reportsNote: (r) => r.length ? `Monthly reports (written after each month ends, never edited): ${r.map((m) => `<a href="data/reports/${m}.json">${m}</a>`).join(' · ')}` : 'Monthly reports: one JSON per completed month, written once and never edited; the first will be 2026-09.',
    qH: 'The conclusion, in numbers',
