    qDDD2: (sc) => `same-state history · scenario model ${sc}`,
    qSources: 'Why two sources differ: “same-state history” uses only months since 1993 when this rule was in the same state (e.g. Offensive, no tightening shock) — closer to today’s decision but a small sample; the “scenario model” uses every month since 1955 weighted by 7 facts — a large sample but weak evidence, so it stays near the long-run average. The range between them is more trustworthy than either number.',
    qMed: 'SPY in 12 months (median)',
    qMedD: (r, lo, hi) => `${r}; 90% range ${lo} – ${hi}`,
    qDD: 'Chance of a 10%+ drawdown on the way',
