      GFDEGDQ188S: ['Federal debt / GDP', 'U.S. Treasury & BEA', 'Q', '⑤ government leverage'],
      DFF: ['Effective federal funds rate', 'Federal Reserve Bank of New York', 'D', 'tightening-shock signal; ⑦ hiking cycles'],
